"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[810],{8620:e=>{e.exports=JSON.parse('{"functions":[{"name":"after","desc":"Schedules a function to execute once after `delay` seconds. The Handle is\\nautomatically cancelled after the function runs.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"},{"name":"delay","desc":"Delay in seconds. Values \u2264 0 execute on the next frame.","lua_type":"number"},{"name":"fn","desc":"The function to execute.","lua_type":"() -> ()"},{"name":"config","desc":"Optional configuration table.","lua_type":"{name: string?}?"}],"returns":[{"desc":"","lua_type":"Handle"}],"function_type":"static","source":{"line":394,"path":"src/Chrono.luau"}},{"name":"every","desc":"Schedules a function to execute immediately and then repeatedly every `interval`\\nseconds. Respects the Scope\'s `timeScale`.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"},{"name":"interval","desc":"Time between executions in seconds.","lua_type":"number"},{"name":"fn","desc":"The function to execute.","lua_type":"() -> ()"},{"name":"config","desc":"Optional configuration table.","lua_type":"{name: string?}?"}],"returns":[{"desc":"","lua_type":"Handle"}],"function_type":"static","source":{"line":418,"path":"src/Chrono.luau"}},{"name":"frame","desc":"Schedules a function to execute every frame via `RunService.Heartbeat`. Unlike\\nother task types, `frame` tasks always fire even when the Scope is paused \u2014\\nthey receive `dt = 0` instead of the real frame delta.\\n\\nTasks run in order of creation, after all `tick` tasks for the frame.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"},{"name":"fn","desc":"Called each frame. `dt` is the frame delta in seconds, or `0` when the Scope is paused.","lua_type":"(dt: number) -> ()"},{"name":"config","desc":"Optional configuration table.","lua_type":"{name: string?}?"}],"returns":[{"desc":"","lua_type":"Handle"}],"function_type":"static","source":{"line":441,"path":"src/Chrono.luau"}},{"name":"tick","desc":"Schedules a function to execute at a fixed frequency, independent of frame rate.\\nIf the frame rate drops below `hz`, the function fires multiple times per frame\\nto compensate. Respects the Scope\'s `timeScale`.\\n\\nTasks run in order of creation, before all `frame` tasks for the frame.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"},{"name":"hz","desc":"Target executions per second (e.g. `60` for 60 hz).","lua_type":"number"},{"name":"fn","desc":"Called with a fixed delta of `1/hz` on each tick.","lua_type":"(dt: number) -> ()"},{"name":"config","desc":"Optional configuration. `maxCatchup` caps how many times the task can fire in a single frame, preventing hitches after freezes (default: unlimited).","lua_type":"{name: string?, maxCatchup: number?}?"}],"returns":[{"desc":"","lua_type":"Handle"}],"function_type":"static","source":{"line":464,"path":"src/Chrono.luau"}},{"name":"pause","desc":"Pauses all tasks in this Scope. Timers do not advance while paused. `frame`\\ntasks still fire each frame but receive `dt = 0`.\\n\\nCalling `pause()` on an already-paused Scope is a no-op.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"}],"returns":[],"function_type":"static","source":{"line":482,"path":"src/Chrono.luau"}},{"name":"resume","desc":"Resumes all tasks in this Scope after a pause. No time is backfilled \u2014 timers\\ncontinue from where they were when the Scope was paused.","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"Scope is destroyed\\"","desc":"Thrown if the Scope was destroyed."}],"source":{"line":495,"path":"src/Chrono.luau"}},{"name":"setTimeScale","desc":"Sets the time multiplier for this Scope. Affects how fast `after`, `every`, and\\n`tick` tasks advance. `frame` tasks always receive wall-clock `dt` regardless.\\n\\n| `scale` | Effect |\\n| ------- | ------ |\\n| `1.0`   | Normal speed (default) |\\n| `0.5`   | Half speed \u2014 slow motion |\\n| `2.0`   | Double speed \u2014 fast-forward |\\n| `0`     | Freezes time (distinct from `pause()`) |","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"},{"name":"scale","desc":"Time multiplier. Negative values have undefined behavior.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":515,"path":"src/Chrono.luau"}},{"name":"destroy","desc":"Permanently destroys this Scope and cancels all its tasks. All child Handles\\nbecome invalid. This operation cannot be undone.\\n\\n:::note\\nAlso available as `scope:Destroy()` for compatibility with [Trove](https://sleitnick.github.io/RbxUtil/api/Trove)\\nand similar cleanup utilities.\\n:::","params":[{"name":"self","desc":"","lua_type":"ScopeInternal"}],"returns":[],"function_type":"static","source":{"line":531,"path":"src/Chrono.luau"}}],"properties":[{"name":"timeScale","desc":"The current time multiplier for this Scope. Affects how fast `after`, `every`,\\nand `tick` tasks advance. Defaults to `1.0`. Modify via `setTimeScale()`.","lua_type":"number","readonly":true,"source":{"line":293,"path":"src/Chrono.luau"}},{"name":"isPaused","desc":"Whether this Scope is currently paused.","lua_type":"boolean","readonly":true,"source":{"line":301,"path":"src/Chrono.luau"}},{"name":"isDestroyed","desc":"Whether this Scope has been permanently destroyed. A destroyed Scope cannot\\nbe used and all its child Handles are invalid.","lua_type":"boolean","readonly":true,"source":{"line":310,"path":"src/Chrono.luau"}},{"name":"elapsedTime","desc":"Total time elapsed in this Scope in seconds, scaled by `timeScale`. Does not\\nadvance while the Scope is paused.","lua_type":"number","readonly":true,"source":{"line":319,"path":"src/Chrono.luau"}}],"types":[],"name":"Scope","desc":"A container for scheduled work. All tasks within a Scope share the same\\nlifecycle: pausing, resuming, or destroying the Scope affects every task\\nregistered to it.\\n\\nCreated via `chrono.scope()`.\\n\\n```lua\\nlocal scope = chrono.scope({ timeScale = 0.5 })\\n\\nscope:tick(60, function(dt)\\n\\tplayer.position += player.velocity * dt\\nend)\\n\\nscope:after(10, function()\\n\\tscope:destroy() -- cleans up all tasks at once\\nend)\\n```","source":{"line":284,"path":"src/Chrono.luau"}}')}}]);